def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 3 or no_water >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 140:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2

    if tight_supply:
        urgency += 2
    elif not loose_supply:
        urgency += 1

    urgency += desperate_count

    if urgency >= 6:
        target = max(DAILY_SALARY * 1.35, highest_prev + 4.0, avg_prev + 8.0)
    elif urgency >= 4:
        target = max(DAILY_SALARY * 1.0, highest_prev + 2.0, avg_prev + 4.0)
    elif urgency >= 2:
        target = max(DAILY_SALARY * 0.72, avg_prev * 0.92)
    else:
        target = DAILY_SALARY * 0.42

    if loose_supply and hp >= 6 and no_water == 0:
        target *= 0.75

    if highest_prev >= 180 and urgency <= 3:
        target = min(target, DAILY_SALARY * 0.55)

    if rich_count >= 2 and tight_supply and urgency >= 3:
        target = max(target, highest_prev + 3.0)

    if day >= 8:
        target *= 1.12

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = DAILY_SALARY * (10 - day) * 0.18

    affordable = max(0.0, budget - reserve_floor)
    if urgency >= 5:
        affordable = budget

    bid = min(target, affordable)

    if bid < 0:
        bid = 0.0
    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(budget, highest_prev + 2.5, DAILY_SALARY * 2.2))
        bid = min(bid, budget)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Infer opponent aggressiveness from yesterday traces
    prev_bids = []
    for oid, o in alive_opps:
        tr = o.get('previous_trace', {})
        b = tr.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else 0.0

    # Tight supply implies need to outbid more; use a soft pressure score
    # supply in [15,25] => remaining slack in [0,2] relative to WATER_REQ
    slack = (supply - WATER_REQ) / float(WATER_REQ)  # ~0.67 to 1.78
    tightness = 1.0 - max(0.0, min(1.0, (slack - 0.6) / 1.2))  # higher when closer to 9

    # If someone previously bid extremely high, assume they will continue anchoring.
    anchor = 0.0
    if highest_prev_bid >= DAILY_SALARY * 1.6:
        anchor = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.9:
        anchor = 0.6

    # Base bid: aim to be competitive but not reckless.
    # Use a target around a fraction of the anchor and tightness.
    base = DAILY_SALARY * (0.45 + 0.35 * tightness + 0.25 * anchor)

    # If we see a strong anchor, try to slightly exceed the typical high bidder yesterday.
    if highest_prev_bid > 0:
        # Don't chase the absolute max; use second-highest as a safer proxy.
        target = max(base, second_prev_bid * 0.95 + 2.0)
    else:
        target = base

    # My health/budget constraints: if low hp, pay more to survive; if high hp, conserve.
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    if hp <= 2.0:
        mult = 0.95
    elif hp <= 4.0:
        mult = 0.85
    elif hp <= 7.0:
        mult = 0.75
    else:
        mult = 0.65

    # Also consider no_water_days: if already accruing, increase urgency.
    no_water_days = int(my_status.get('no_water_days', 0))
    if no_water_days >= 2:
        mult += 0.15
    elif no_water_days >= 1:
        mult += 0.07

    bid = target * mult

    # Ensure bid is within reasonable bounds and budget-limited.
    # Keep some budget for future days; never exceed 95% of budget.
    cap = max(0.0, budget * 0.95)
    bid = min(bid, cap)

    # Lower bound: if budget allows, bid at least a small fraction to avoid being shut out.
    floor = min(cap, DAILY_SALARY * (0.35 + 0.2 * tightness))
    bid = max(bid, floor)

    # Final safety: if budget is tiny, bid whatever possible.
    if budget <= 1.0:
        return max(0.0, budget)

    return float(bid)

